import{_ as e,o as r,c as t,x as i}from"./chunks/framework.DzQQ_lrg.js";const l="/xi-kari-skill/handbook/images/mars-climate-orbiter.svg",f=JSON.parse('{"title":"火星气候轨道器：文件传到了，数值的含义却没有对上","description":"","frontmatter":{"slug":"mars-climate-orbiter","title":"火星气候轨道器：文件传到了，数值的含义却没有对上","kind":"真实案例","source_type":"官方事故调查报告","concepts":["representation-loss","local-and-whole-chain"]},"headers":[],"relativePath":"cases/mars-climate-orbiter.md","filePath":"cases/mars-climate-orbiter.md"}'),o={name:"cases/mars-climate-orbiter.md"};function s(n,a,h,c,p,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="火星气候轨道器-文件传到了-数值的含义却没有对上" tabindex="-1">火星气候轨道器：文件传到了，数值的含义却没有对上 <a class="header-anchor" href="#火星气候轨道器-文件传到了-数值的含义却没有对上" aria-label="Permalink to &quot;火星气候轨道器：文件传到了，数值的含义却没有对上&quot;">​</a></h1><p>1999年9月23日，火星气候轨道器在抵达火星时失联。它原计划研究火星气候，并承担通信中继任务。NASA将这次任务列为失败，并将单位转换错误造成的导航偏差列为原因。<a href="https://science.nasa.gov/mission/mars-climate-orbiter/" target="_blank" rel="noreferrer">NASA任务资料</a></p><h2 id="事故报告确认了什么" tabindex="-1">事故报告确认了什么 <a class="header-anchor" href="#事故报告确认了什么" aria-label="Permalink to &quot;事故报告确认了什么&quot;">​</a></h2><p>调查报告指出，地面软件SM_FORCES输出的推进器冲量使用了磅力秒，接口规范要求的却是牛顿秒。导航软件按规定单位解释数据，因而将相关推力影响低估了约4.45倍。报告同时列出验证、沟通、人员与培训等促成因素。单位要求已经写在规范里，实际数据却没有遵守要求，既有检查也没有及时捕获这一问题。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第6—7、16—17页</a></p><figure class="concept-figure"><img src="'+l+'" alt="mars-climate-orbiter案例的关系图"><figcaption>根据本页官方资料绘制，保留图示的适用范围。</figcaption></figure><h2 id="从这里读懂一个区别" tabindex="-1">从这里读懂一个区别 <a class="header-anchor" href="#从这里读懂一个区别" aria-label="Permalink to &quot;从这里读懂一个区别&quot;">​</a></h2><p>这个案例可以帮助阅读《Xikari-条件结构与转化论》中“表示充分与实际执行正确分别检验”的区别。接收一个数值文件，能够确认传递发生，却还要核对它保留了什么含义、接受方采用了什么解释规则，以及这些规则是否符合本次任务。</p><p>原文在附录C.7用形式例子区分两类问题：必要区别在表示中已经丢失，和信息足够但实际规则用错。前者不能只靠换一条计算规则补回；后者也不必一律归咎于信息缺失。本案例的具体故障由NASA调查报告认定，原文提供的是阅读这种区别的提问方式：问题究竟发生在数据含义、映射关系、使用规则，还是后续执行？不能仅凭“接口有输出”就合并回答。<a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-7">阅读原文：附录C.7</a></p><h2 id="看图时保留什么" tabindex="-1">看图时保留什么 <a class="header-anchor" href="#看图时保留什么" aria-label="Permalink to &quot;看图时保留什么&quot;">​</a></h2><p>从推进器活动，到地面软件、数据文件和导航计算，每个节点都有对应量与单位。单位不是可忽略的文字标签；同一串数字进入不同解释规则，会改变计算结果。图中并列了“规范要求的单位”和“实际输出的单位”，接口处的差异也就显露出来。</p><p>同时，单个接口失配并不自动回答全部责任分配。原文将实际承接、成本承担、停止权与责任主体分开；谁写入文件、谁使用文件、谁负责验证，各自需要具体依据，不能从谁最可见直接得出谁承担全部责任。<a href="/xi-kari-skill/handbook/theory/part-02.html#section-2-8">阅读原文：§2.8与责任边界</a></p><p>本页依据事故调查材料帮助辨认接口、规则和结果的区别。它不由一个事故证明所有跨组织协作必然失败，也不把事后能够解释事故当成事前已经能够预测事故。</p><h2 id="是信息丢了-还是规范没有被遵守" tabindex="-1">是信息丢了，还是规范没有被遵守 <a class="header-anchor" href="#是信息丢了-还是规范没有被遵守" aria-label="Permalink to &quot;是信息丢了，还是规范没有被遵守&quot;">​</a></h2><p>报告第4节写明，软件接口规范（SIS）定义了AMD（角动量卸载）文件的格式和单位，而规范没有被遵守。数据异常在1999年4月就被看出，单位不符却到9月29日、失联六天之后才查明；此后的导航估算改用修正后的数值重算了轨道。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第13—14、16、18页</a></p><p>这个单位错误不属于上文的第一类问题（必要区别在表示中已经丢失）：不同的冲量在文件里仍是不同的数，知道实际单位就能换算回来。按附录C.7的区分，本页把它读作实际执行一侧的问题。这是借原文概念作的解读，报告不用这套说法；原文也说，那个形式例子“不要求每个现实故障都能被唯一分类”。<a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-7">阅读原文：附录C.7</a></p><h2 id="报告怎样说验证环节" tabindex="-1">报告怎样说验证环节 <a class="header-anchor" href="#报告怎样说验证环节" aria-label="Permalink to &quot;报告怎样说验证环节&quot;">​</a></h2><p>报告列出八项促成因素，第八项专讲验证与确认，四句话的确定程度不同：接口规范制定了，却没有在小作用力（small forces）地面软件的开发和测试中被正确使用；检验这套软件的表现及其是否符合规范的端到端测试“看来没有完成”（did not appear to be accomplished）；地面软件是否完成了独立验证与确认，“并不清楚”（it was not clear）；接口控制过程和特定地面系统接口的验证没有完成，或完成得不够严格。这是第一阶段报告，所列促成因素侧重于可能影响火星极地着陆器的事项。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第7、15、25页</a></p><h2 id="这不是-两段都有效-反例的实例" tabindex="-1">这不是“两段都有效”反例的实例 <a class="header-anchor" href="#这不是-两段都有效-反例的实例" aria-label="Permalink to &quot;这不是“两段都有效”反例的实例&quot;">​</a></h2><p>原文附录C.12把“转换能否组成同一最终答案”和“因果作用能否串联”分开。本页把这次事故读作前一个问题：前段给出的量与后段采用的含义没有对上。§2.4.2的<a href="/xi-kari-skill/handbook/concepts/chain.html">两类人反例</a>属于后一个问题，是给定函数的形式构造；报告没有估计任何平均作用，两者不能互相充当证据。<a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-12">阅读原文：附录C.12</a>、<a href="/xi-kari-skill/handbook/theory/part-02.html#section-2-4-2">§2.4.2</a></p><h2 id="自测与参考答案" tabindex="-1">自测与参考答案 <a class="header-anchor" href="#自测与参考答案" aria-label="Permalink to &quot;自测与参考答案&quot;">​</a></h2><ol><li><strong>规范写对了，接口就没有问题吗？</strong> 不是。失配出在规范和实际交付之间，两者要对照着看。</li><li><strong>单位错误是这次事故的全部解释吗？</strong> 不是。报告认定它是根本原因，但也写道：项目中难免出错，通常有足够的流程在错误危及任务之前把它拦住，这一次没有拦住；另有八项促成因素。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第7页</a></li><li><strong>报告说端到端测试“从未做过”吗？</strong> 没有，写的是“看来没有完成”；独立验证与确认是否完成，写的是“并不清楚”。转述时不能改成确定的否定。</li></ol><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="./../concepts/responsibility.html">实际承接与责任依据</a></li><li><a href="./../concepts/chain.html">从局部作用到整条链</a></li></ul>',23)])])}const b=e(o,[["render",s]]);export{f as __pageData,b as default};
